import sys
import heapq
from array import array


def solve():
    read = sys.stdin.buffer.readline
    n, m = map(int, read().split())
    INF = 4294967295
    if m <= 4 * n:
        graph = [[] for _ in range(n)]
        for _ in range(m):
            u, v, w = map(int, read().split())
            u -= 1
            v -= 1
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]
        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            if u == n - 1:
                return cost
            for v, w in graph[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))
        return -1

    # Lower triangle: edge {u,v}, u>v, occupies offset[u]+v.
    offset = [u * (u - 1) // 2 for u in range(n)]
    weights = array("I", [INF])
    assert weights.itemsize == 4
    weights *= n * (n - 1) // 2
    for _ in range(m):
        u, v, w = map(int, read().split())
        u -= 1
        v -= 1
        if u < v:
            u, v = v, u
        if u == v:
            continue
        index = offset[u] + v
        if w < weights[index]:
            weights[index] = w
    dist = array("I", [INF]) * n
    used = bytearray(n)
    dist[0] = 0
    for _ in range(n):
        best = INF
        u = -1
        for v in range(n):
            if not used[v] and dist[v] < best:
                best = dist[v]
                u = v
        if u == -1:
            return -1
        if u == n - 1:
            return best
        used[u] = 1
        base = offset[u]
        for v in range(u):
            if not used[v]:
                w = weights[base + v]
                candidate = best if best >= w else w
                if candidate < dist[v]:
                    dist[v] = candidate
        for v in range(u + 1, n):
            if not used[v]:
                w = weights[offset[v] + u]
                candidate = best if best >= w else w
                if candidate < dist[v]:
                    dist[v] = candidate
    return -1


print(solve())

