    if (m <= 4 * n) {
        vector<vector<pair<int, uint32_t>>> graph(n);
        for (int i = 0; i < m; ++i) {
            int u, v;
            uint32_t w;
            cin >> u >> v >> w;
            --u;
            --v;
            graph[u].push_back({v, w});
            graph[v].push_back({u, w});
        }
        vector<uint32_t> dist(n, INF);
        using Entry = pair<uint32_t, int>;
        priority_queue<Entry, vector<Entry>, greater<Entry>> heap;
        dist[0] = 0;
        heap.push({0, 0});
        while (!heap.empty()) {
            auto [cost, u] = heap.top();
            heap.pop();
            if (cost != dist[u])
                continue;
            if (u == n - 1) {
                cout << cost << '\n';
                return 0;
            }
            for (auto [v, w] : graph[u]) {
                uint32_t candidate = max(cost, w);
                if (candidate < dist[v]) {
                    dist[v] = candidate;
                    heap.push({candidate, v});
                }
            }
        }
        cout << -1 << '\n';
        return 0;
    }
    vector<size_t> offset(n);
    for (size_t u = 0; u < size_t(n); ++u)
        offset[u] = u * (u - 1) / 2;
    vector<uint32_t> weights(size_t(n) * (n - 1) / 2, INF);
    for (int i = 0; i < m; ++i) {
        int u, v;
        uint32_t w;
        cin >> u >> v >> w;
        --u;
        --v;
        if (u < v)
            swap(u, v);
        if (u == v)
            continue;
        size_t index = offset[u] + v;
        weights[index] = min(weights[index], w);
    }
    vector<uint32_t> dist(n, INF);
    vector<unsigned char> used(n);
    dist[0] = 0;
    for (int step = 0; step < n; ++step) {
        uint32_t best = INF;
        int u = -1;
        for (int v = 0; v < n; ++v) {
            if (!used[v] && dist[v] < best) {
                best = dist[v];
                u = v;
            }
        }
        if (u == -1)
            break;
        if (u == n - 1) {
            cout << best << '\n';
            return 0;
        }
        used[u] = 1;
        for (int v = 0; v < u; ++v) {
            if (!used[v])
                dist[v] = min(dist[v], max(best, weights[offset[u] + v]));
        }
        for (int v = u + 1; v < n; ++v) {
            if (!used[v])
                dist[v] = min(dist[v], max(best, weights[offset[v] + u]));
        }
    }
    cout << -1 << '\n';
}

