import sys
import heapq
from bisect import bisect_left, bisect_right


def solve():
    it = iter(sys.stdin.buffer.read().split())
    n = int(next(it))
    moves = []
    opposite = {b"U": b"D", b"D": b"U", b"L": b"R", b"R": b"L"}
    for _ in range(n):
        d, length = next(it), int(next(it))
        if moves and opposite[d] == moves[-1][0]:
            break
        if moves and d == moves[-1][0]:
            moves[-1][1] += length
        else:
            moves.append([d, length])
    segments = []
    x = y = 0
    for d, length in moves:
        xx = x + (length if d == b"R" else -length if d == b"L" else 0)
        yy = y + (length if d == b"U" else -length if d == b"D" else 0)
        segments.append((x, y, xx, yy))
        x, y = xx, yy
    count = len(segments)
    best = count
    # Collinear overlaps, including a single common endpoint.
    for horizontal in (True, False):
        rows = []
        for i, (x, y, xx, yy) in enumerate(segments):
            if (y == yy) == horizontal:
                fixed, lo, hi = (
                    (y, min(x, xx), max(x, xx))
                    if horizontal
                    else (x, min(y, yy), max(y, yy))
                )
                rows.append((fixed, lo, hi, i))
        rows.sort()
        heap = []
        last = None
        for fixed, lo, hi, i in rows:
            if fixed != last:
                heap = []
                last = fixed
            while heap and heap[0][1] < lo:
                heapq.heappop(heap)
            if heap:
                best = min(best, max(i, heap[0][0]))
            heapq.heappush(heap, (i, hi))
    ys = sorted({y for x, y, xx, yy in segments if y == yy})
    if ys:
        size = 1
        while size < len(ys):
            size *= 2
        tree = [count] * (2 * size)
        heaps = [[] for _ in ys]
        active = [False] * count
        position = [-1] * count
        events = []
        for i, (x, y, xx, yy) in enumerate(segments):
            if y == yy:
                p = bisect_left(ys, y)
                position[i] = p
                events.append((min(x, xx), 0, i))
                events.append((max(x, xx), 2, i))
            else:
                events.append((x, 1, i))
        events.sort()

        def refresh(p):
            h = heaps[p]
            while h and not active[h[0]]:
                heapq.heappop(h)
            node = size + p
            tree[node] = h[0] if h else count
            node //= 2
            while node:
                value = min(tree[node * 2], tree[node * 2 + 1])
                if value == tree[node]:
                    break
                tree[node] = value
                node //= 2

        def query(left, right):
            left += size
            right += size
            result = count
            while left < right:
                if left & 1:
                    result = min(result, tree[left])
                    left += 1
                if right & 1:
                    right -= 1
                    result = min(result, tree[right])
                left //= 2
                right //= 2
            return result

        for x, kind, i in events:
            if kind != 1:
                p = position[i]
                active[i] = kind == 0
                if kind == 0:
                    heapq.heappush(heaps[p], i)
                refresh(p)
            else:
                _, y, _, yy = segments[i]
                left = bisect_left(ys, min(y, yy))
                right = bisect_right(ys, max(y, yy))
                removed = []
                while True:
                    j = query(left, right)
                    if j == count or abs(i - j) != 1:
                        break
                    p = position[j]
                    heapq.heappop(heaps[p])
                    removed.append(j)
                    refresh(p)
                if j != count:
                    best = min(best, max(i, j))
                for j in removed:
                    p = position[j]
                    heapq.heappush(heaps[p], j)
                    refresh(p)
    distance = sum(moves[i][1] for i in range(best))
    if best < count:
        x, y, xx, yy = segments[best]
        nearest = abs(xx - x) + abs(yy - y)
        for a, b, c, d in segments[: max(0, best - 1)]:
            if y == yy:
                if b == d:
                    if b != y:
                        continue
                    lo, hi = max(min(x, xx), min(a, c)), min(max(x, xx), max(a, c))
                    if lo > hi:
                        continue
                    crossx = lo if xx > x else hi
                else:
                    crossx = a
                    if not (
                        min(x, xx) <= a <= max(x, xx) and min(b, d) <= y <= max(b, d)
                    ):
                        continue
                nearest = min(nearest, abs(crossx - x))
            else:
                if a == c:
                    if a != x:
                        continue
                    lo, hi = max(min(y, yy), min(b, d)), min(max(y, yy), max(b, d))
                    if lo > hi:
                        continue
                    crossy = lo if yy > y else hi
                else:
                    crossy = b
                    if not (
                        min(y, yy) <= b <= max(y, yy) and min(a, c) <= x <= max(a, c)
                    ):
                        continue
                nearest = min(nearest, abs(crossy - y))
        distance += nearest
    print(distance)


solve()

