#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;
struct Segment {
    ll x, y, xx, yy;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<char, ll>> moves;
    auto opposite = [](char a, char b) {
        return (a == 'U' && b == 'D') || (a == 'D' && b == 'U') ||
               (a == 'L' && b == 'R') || (a == 'R' && b == 'L');
    };
    for (int i = 0; i < n; i++) {
        char d;
        ll len;
        cin >> d >> len;
        if (!moves.empty() && opposite(d, moves.back().first))
            break;
        if (!moves.empty() && d == moves.back().first)
            moves.back().second += len;
        else
            moves.push_back({d, len});
    }
    vector<Segment> s;
    ll x = 0, y = 0;
    for (auto [d, len] : moves) {
        ll xx = x + (d == 'R'   ? len
                     : d == 'L' ? -len
                                : 0),
           yy = y + (d == 'U'   ? len
                     : d == 'D' ? -len
                                : 0);
        s.push_back({x, y, xx, yy});
        x = xx;
        y = yy;
    }
    int m = s.size(), best = m;
    for (bool horizontal : {true, false}) {
        vector<tuple<ll, ll, ll, int>> rows;
        for (int i = 0; i < m; i++) {
            auto [x, y, xx, yy] = s[i];
            if ((y == yy) == horizontal) {
                if (horizontal)
                    rows.emplace_back(y, min(x, xx), max(x, xx), i);
                else
                    rows.emplace_back(x, min(y, yy), max(y, yy), i);
            }
        }
        sort(rows.begin(), rows.end());
        priority_queue<pair<int, ll>, vector<pair<int, ll>>, greater<pair<int, ll>>>
            heap;
        ll last = LLONG_MIN;
        for (auto [fixed, lo, hi, i] : rows) {
            if (fixed != last) {
                heap = {};
                last = fixed;
            }
            while (!heap.empty() && heap.top().second < lo)
                heap.pop();
            if (!heap.empty())
                best = min(best, max(i, heap.top().first));
            heap.push({i, hi});
        }
    }
    vector<ll> ys;
    for (auto z : s)
        if (z.y == z.yy)
            ys.push_back(z.y);
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    if (!ys.empty()) {
        int size = 1;
        while (size < (int)ys.size())
            size *= 2;
        vector<int> tree(2 * size, m), position(m, -1);
        vector<bool> active(m, false);
        vector<priority_queue<int, vector<int>, greater<int>>> heaps(ys.size());
        vector<tuple<ll, int, int>> events;
        for (int i = 0; i < m; i++) {
            auto z = s[i];
            if (z.y == z.yy) {
                position[i] = lower_bound(ys.begin(), ys.end(), z.y) - ys.begin();
                events.emplace_back(min(z.x, z.xx), 0, i);
                events.emplace_back(max(z.x, z.xx), 2, i);
            } else
                events.emplace_back(z.x, 1, i);
        }
        sort(events.begin(), events.end());
        auto refresh = [&](int p) {
            auto &h = heaps[p];
            while (!h.empty() && !active[h.top()])
                h.pop();
            int node = size + p;
            tree[node] = h.empty() ? m : h.top();
            for (node /= 2; node; node /= 2)
                tree[node] = min(tree[node * 2], tree[node * 2 + 1]);
        };
        auto query = [&](int l, int r) {
            int ans = m;
            for (l += size, r += size; l < r; l /= 2, r /= 2) {
                if (l & 1)
                    ans = min(ans, tree[l++]);
                if (r & 1)
                    ans = min(ans, tree[--r]);
            }
            return ans;
        };
        for (auto [at, kind, i] : events) {
            if (kind != 1) {
                int p = position[i];
                active[i] = kind == 0;
                if (kind == 0)
                    heaps[p].push(i);
                refresh(p);
            } else {
                auto z = s[i];
                int l = lower_bound(ys.begin(), ys.end(), min(z.y, z.yy)) - ys.begin(),
                    r = upper_bound(ys.begin(), ys.end(), max(z.y, z.yy)) - ys.begin();
                vector<int> removed;
                int j;
                while (true) {
                    j = query(l, r);
                    if (j == m || abs(i - j) != 1)
                        break;
                    int p = position[j];
                    heaps[p].pop();
                    removed.push_back(j);
                    refresh(p);
                }
                if (j != m)
                    best = min(best, max(i, j));
                for (int id : removed) {
                    heaps[position[id]].push(id);
                    refresh(position[id]);
                }
            }
        }
    }
    ll distance = 0;
    for (int i = 0; i < best; i++)
        distance += moves[i].second;
    if (best < m) {
        auto [x, y, xx, yy] = s[best];
        ll near = abs(xx - x) + abs(yy - y);
        for (int i = 0; i < best - 1; i++) {
            auto [a, b, c, d] = s[i];
            if (y == yy) {
                ll t;
                if (b == d) {
                    if (b != y)
                        continue;
                    ll lo = max(min(x, xx), min(a, c)), hi = min(max(x, xx), max(a, c));
                    if (lo > hi)
                        continue;
                    t = xx > x ? lo : hi;
                } else {
                    t = a;
                    if (!(min(x, xx) <= a && a <= max(x, xx) && min(b, d) <= y &&
                          y <= max(b, d)))
                        continue;
                }
                near = min(near, abs(t - x));
            } else {
                ll t;
                if (a == c) {
                    if (a != x)
                        continue;
                    ll lo = max(min(y, yy), min(b, d)), hi = min(max(y, yy), max(b, d));
                    if (lo > hi)
                        continue;
                    t = yy > y ? lo : hi;
                } else {
                    t = b;
                    if (!(min(y, yy) <= b && b <= max(y, yy) && min(a, c) <= x &&
                          x <= max(a, c)))
                        continue;
                }
                near = min(near, abs(t - y));
            }
        }
        distance += near;
    }
    cout << distance << '\n';
}

