struct E {
    int v, rev, cap;
    ll c;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<E>> g(n);
    for (int i = 0, u, v, r, c; i < m; i++) {
        cin >> u >> v >> r >> c;
        --u;
        --v;
        if (u == v)
            continue;
        int a = g[u].size(), b = g[v].size();
        g[u].push_back({v, b, r, c});
        g[v].push_back({u, a, 0, -c});
    }
    vector<ll> h(n);
    ll ans = 0;
    int flow = 0;
    const ll INF = 1LL << 60;
    while (flow < k) {
        vector<ll> d(n, INF);
        vector<int> pv(n), pe(n);
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> q;
        d[0] = 0;
        q.push({0, 0});
        while (!q.empty()) {
            auto [du, u] = q.top();
            q.pop();
            if (du != d[u])
                continue;
            for (int i = 0; i < (int)g[u].size(); i++) {
                auto &e = g[u][i];
                ll z = du + e.c + h[u] - h[e.v];
                if (e.cap && z < d[e.v]) {
                    d[e.v] = z;
                    pv[e.v] = u;
                    pe[e.v] = i;
                    q.push({z, e.v});
                }
            }
        }
        if (d[n - 1] == INF)
            break;
        for (int u = 0; u < n; u++)
            if (d[u] < INF)
                h[u] += d[u];
        int f = k - flow;
        for (int v = n - 1; v; v = pv[v])
            f = min(f, g[pv[v]][pe[v]].cap);
        for (int v = n - 1; v; v = pv[v]) {
            auto &e = g[pv[v]][pe[v]];
            ans += f * e.c;
            e.cap -= f;
            g[v][e.rev].cap += f;
        }
        flow += f;
    }
    cout << (flow == k ? ans : -1) << '\n';
}

