struct Tree {
    vector<int> lo, hi, lz;
    Tree(int n) : lo(4 * n), hi(4 * n), lz(4 * n) {
    }
    void apply(int v, int d) {
        lo[v] += d;
        hi[v] += d;
        lz[v] += d;
    }
    void add(int v, int l, int r, int c, int d) {
        if (r <= c) {
            apply(v, d);
            return;
        }
        if (lz[v]) {
            apply(2 * v, lz[v]);
            apply(2 * v + 1, lz[v]);
            lz[v] = 0;
        }
        int m = (l + r) / 2;
        add(2 * v, l, m, c, d);
        if (c > m)
            add(2 * v + 1, m + 1, r, c, d);
        lo[v] = min(lo[2 * v], lo[2 * v + 1]);
        hi[v] = max(hi[2 * v], hi[2 * v + 1]);
    }
};
