    v = sum(cp[i] * fact[b - k - i] for i in range(p + 1)) % MOD
    coefficient = choose(R, k) * choose(C, k) % MOD * fact[k] % MOD
    answer = (answer + (-1 if k % 2 else 1) * coefficient * u * v) % MOD
print(answer)

