                ra[r] = ca[c] = 1;
            if (g[r][c] == 'B')
                rb[r] = cb[c] = 1;
        }
    int a = n - accumulate(ra.begin(), ra.end(), 0),
        b = n - accumulate(rb.begin(), rb.end(), 0), R = 0, C = 0, p = 0, q = 0;
    for (int i = 0; i < n; i++) {
        R += !ra[i] && !rb[i];
        C += !ca[i] && !cb[i];
    }
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) {
            p += g[r][c] == 'A' && !rb[r] && !cb[c];
            q += g[r][c] == 'B' && !ra[r] && !ca[c];
        }
