    ll ans = 0;
    for (int k = 0; k <= min(R, C); k++) {
        ll u = 0, v = 0;
        for (int j = 0; j <= q; j++) {
            ll term = choose(q, j) * f[a - k - j] % MOD;
            u = (u + (j % 2 ? MOD - term : term)) % MOD;
        }
