using M = array<ll, 4>;
M mul(M a, M b) {
    return {(a[0] * b[0] + a[1] * b[2]) % MOD, (a[0] * b[1] + a[1] * b[3]) % MOD,
            (a[2] * b[0] + a[3] * b[2]) % MOD, (a[2] * b[1] + a[3] * b[3]) % MOD};
}
ll ways(ll n, int e) {
    M a{0, e, 1, 1}, r{1, 0, 0, 1};
    for (--n; n; n /= 2, a = mul(a, a))
        if (n & 1)
            r = mul(r, a);
    return (r[0] * e + r[1] + r[2] * e + r[3]) % MOD;
}
