                    e[j][v] = (e[j][v] + z * (j + 1)) % MOD;
                if (j + 1 <= lim)
                    e[j + 1][v] = (e[j + 1][v] + z) % MOD;
                if (j)
                    e[j - 1][v] = (e[j - 1][v] + z * j) % MOD;
            }
        d.swap(e);
    }
    ll ans = 0;
    for (ll z : d[0])
        ans = (ans + z) % MOD;
    cout << ans << '\n';
}

