        return 0
    front = {start}
    back = {target}
    da = {start: 0}
    db = {target: 0}
    while front:
        if len(front) > len(back):
            front, back = back, front
            da, db = db, da
        nxt = set()
        for s in front:
            d = da[s] + 1
            for i, j in edges:
                a = bytearray(s)
                a[i], a[j] = a[j], a[i]
                v = bytes(a)
                if v in da:
                    continue
                if v in db:
                    return d + db[v]
                da[v] = d
                nxt.add(v)
        front = nxt


