using ll = long long;
const ll MOD = 1000000007;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string start;
    for (int i = 0, x; i < 9; i++) {
        cin >> x;
        start += char('0' + x);
    }
    string goal = "123456789";
    if (start == goal) {
        cout << 0 << '\n';
        return 0;
    }
    vector<pair<int, int>> edges;
    for (int i = 0; i < 9; i++) {
        if (i % 3 < 2)
            edges.push_back({i, i + 1});
        if (i < 6)
            edges.push_back({i, i + 3});
    }
    unordered_set<string> a{start}, b{goal};
    unordered_map<string, int> da{{start, 0}}, db{{goal, 0}};
    while (!a.empty()) {
        if (a.size() > b.size()) {
            swap(a, b);
            swap(da, db);
        }
        unordered_set<string> next;
        for (auto s : a) {
            int d = da[s] + 1;
            for (auto [i, j] : edges) {
                swap(s[i], s[j]);
                if (!da.count(s)) {
                    if (db.count(s)) {
                        cout << d + db[s] << '\n';
                        return 0;
                    }
                    da[s] = d;
                    next.insert(s);
                }
                swap(s[i], s[j]);
            }
        }
        a.swap(next);
    }
}

