        array<I, 10> cnt{};
        for (I f = 1; f <= x; f *= 10) {
            I h = x / (10 * f), c = x / f % 10, l = x % f;
            for (int d = 1; d < 10; d++)
                cnt[d] += h * f + (c > d ? f : c == d ? l + 1 : 0);
            if (h)
                cnt[0] += (h - 1) * f + (c == 0 ? l + 1 : f);
        }
        for (I z : cnt)
            if (z > n)
                return false;
        return true;
    };
    I lo = 0, hi = (I)10 * n;
    while (lo < hi) {
        I m = (lo + hi + 1) / 2;
        if (ok(m))
            lo = m;
        else
            hi = m - 1;
    }
    string out;
    do {
        out += char('0' + lo % 10);
        lo /= 10;
    } while (lo);
    reverse(out.begin(), out.end());
    cout << out << '\n';
}
